#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.zombinator_Animation)]
    public class Zombinator_AnimationBehaviour : HumanoidAnimationBehaviour
    {
        public Zombinator_AnimationBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void ModifyAnimationParameters(Entity entity, int state, ref AnimationParameters parameters)
        {
            base.ModifyAnimationParameters(entity, state, ref parameters);
            if (state == STATE_DEATH && entity.IsInWater())
            {
                parameters.armState = ARM_STATE_SPECIAL_1;
            }
        }
    }
}